result = json.loads(result_str)

# Print all keys except any that contain base64 data
def print_fields(obj, prefix=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if isinstance(v, str) and len(v) > 500:
                print(f'{prefix}{k}: [string, {len(v)} chars, first 200: {v[:200]}...]')
            elif isinstance(v, (dict, list)):
                print(f'{prefix}{k}:')
                print_fields(v, prefix + '  ')
            else:
                print(f'{prefix}{k}: {v}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            print(f'{prefix}[{i}]:')
            print_fields(item, prefix + '  ')
    else:
        s = str(obj)
        if len(s) > 500:
            print(f'{prefix}{s[:200]}...')
        else:
            print(f'{prefix}{obj}')

print_fields(result)
